import { unstable_noStore as noStore } from 'next/cache';

export default function Home() {
  // Log page view without blocking the response
  noStore();

  // Schedule analytics logging after response
  const logAnalytics = async () => {
    try {
      // Simulate analytics service call
      await fetch('https://analytics.example.com/log', {
        method: 'POST',
        body: JSON.stringify({
          event: 'page_view',
          page: 'home',
          timestamp: new Date().toISOString()
        }),
        headers: {
          'Content-Type': 'application/json'
        }
      });
    } catch (error) {
      console.error('Analytics logging failed:', error);
    }
  };

  // Start non-blocking analytics logging
  logAnalytics();

  return (
    <main>
      <h1>Welcome to our site!</h1>
      <p>Your visit has been logged for analytics purposes.</p>
    </main>
  );
}

